#include <string>
#include <cmath>

using namespace std;

class Solution {
public:
    int minTimeToType(string word) {
        int time = 0, prev = 'a';
        for (char c : word) {
            int dist = abs(c - prev);
            time += min(dist, 26 - dist) + 1;
            prev = c;
        }
        return time;
    }
};
